\title{Kernel Patterns: Complete Invariants of Tuples, the Bell Numbers,\\
and the Combinatorial Geometry of the Braid Arrangement}
\author{Aristotle}
\date{26 August 2026}

\begin{document}
\maketitle

\begin{abstract}
For a tuple $x=(x_1,\dots,x_n)$ with entries in a set $X$ we define its \emph{kernel pattern} $\pat(x)$ by $\pat(x)_i=\min\{j: x_j=x_i\}$, the first-occurrence representative of the value at position $i$. We prove that the kernel pattern is a \textbf{complete invariant} of the diagonal action of the symmetric group $\Sym(X)$ on $X^n$ when $X$ is finite: two tuples lie in the same orbit if and only if they have the same kernel pattern. The result is sharp---for a proper subgroup the kernel is no longer complete---and the set of realisable patterns \emph{stabilises} once $|X|\ge n$. Kernel patterns of length $n$ are in canonical bijection with equivalence relations on an $n$-element index set; those using exactly $k$ distinct values are counted by the Stirling number of the second kind $S(n,k)$, and all of them by the Bell number $B_n$. Both counts follow from an explicit delete-the-last-index recursion on the pattern model, yielding as a by-product the identity $B_n=\sum_{k}S(n,k)$ between two independently defined recursions; the initial segment $1,1,2,5,15,52$ (OEIS A000110) is confirmed by exhaustive enumeration of the fixed points of $\pat$. Geometrically, the flat of the braid arrangement $\{v_i=v_j\}_{i<j}$ in $\R^n$ cut out by a tuple depends faithfully on its kernel pattern; inclusion of flats is reverse refinement of kernels, and the dimension of a flat is its number of blocks, so the intersection lattice has $B_n$ elements with $S(n,k)$ of dimension $k$. Refining a pattern by the \emph{ordering} of its blocks gives the \emph{ordered pattern} $\rank(v)$, a complete invariant of the \textbf{face} of the arrangement; each flat with $k$ blocks carries exactly $k!$ faces, so the faces number $\sum_k S(n,k)k!$, the Fubini numbers $1,1,3,13,75,541$ (OEIS A000670), inside which the $n!$ chambers sit as the top stratum.
\end{abstract}

\noindent\textbf{Keywords:} kernel pattern; set partition; Bell numbers; Stirling numbers of the second kind; braid arrangement; intersection lattice; faces and chambers; ordered Bell numbers; complete invariant.

\section{Introduction}

\subsection{The question}

Fix a set $X$ and an integer $n\ge 0$. The symmetric group $\Sym(X)$ acts on the configuration space $X^n$ \emph{diagonally}, by relabelling all coordinates at once,
\[
  \sigma\cdot(x_1,\dots,x_n)=(\sigma x_1,\dots,\sigma x_n).
\]
The orbit classification problem asks: what data about a tuple survives an arbitrary relabelling of the alphabet, and is that data enough to reconstruct the orbit?

A relabelling by a bijection can neither merge two distinct values nor split one value in two, so the only surviving datum is the \emph{coincidence structure}: the equivalence relation
\[
  i\sim_x j \iff x_i=x_j
\]
on the index set $[n]=\{1,\dots,n\}$, called the \emph{kernel} of $x$. What is not a priori clear is that the kernel is \emph{sufficient}. This paper establishes that, quantifies it, and shows the resulting classification is simultaneously algebraic, combinatorial and geometric.

\subsection{Canonical form}

\begin{definition}[Kernel pattern]\label{def:pat}
Let $X$ be a set with decidable equality and $x:[n]\to X$ a tuple. Its \emph{kernel pattern} is $\pat(x):[n]\to[n]$,
\[
  \pat(x)_i=\min\{\,j\in[n]: x_j=x_i\,\}.
\]
The minimum is over a nonempty set (it contains $i$), so $\pat$ is well defined and $\pat(x)_i\le i$.
\end{definition}

\begin{example}
For $x=(\mathrm{r},\mathrm{b},\mathrm{r},\mathrm{g},\mathrm{b})$ one has $\pat(x)=(1,2,1,4,2)$, corresponding to the partition $\{\{1,3\},\{2,5\},\{4\}\}$.
\end{example}

Throughout, $B_n$ denotes the $n$-th Bell number and $S(n,k)$ the Stirling number of the second kind.

\section{The calculus of kernel patterns}

\begin{lemma}[Value stability]\label{lem:val}
For every $i$, $x_{\pat(x)_i}=x_i$.
\end{lemma}
\begin{proof}
$\pat(x)_i$ is by construction a member of $\{j:x_j=x_i\}$.
\end{proof}

\begin{lemma}[Faithfulness]\label{lem:faith}
$\pat(x)_i=\pat(x)_j \iff x_i=x_j$.
\end{lemma}
\begin{proof}
($\Rightarrow$) By Lemma~\ref{lem:val}, $x_i=x_{\pat(x)_i}=x_{\pat(x)_j}=x_j$. ($\Leftarrow$) If $x_i=x_j$ then $\{k:x_k=x_i\}=\{k:x_k=x_j\}$, hence the minima agree.
\end{proof}

\begin{lemma}[Kernel congruence]\label{lem:congr}
If $x:[n]\to X$ and $y:[n]\to Y$ satisfy $x_k=x_l\iff y_k=y_l$ for all $k,l$, then $\pat(x)=\pat(y)$.
\end{lemma}
\begin{proof}
Fix $i$. By Lemma~\ref{lem:val}, $y_{\pat(y)_i}=y_i$, which transfers to $x_{\pat(y)_i}=x_i$; hence $\pat(y)_i$ lies in the set whose minimum defines $\pat(x)_i$, so $\pat(x)_i\le\pat(y)_i$. The symmetric argument gives the converse inequality.
\end{proof}

\begin{theorem}[Invariance]\label{thm:inv}
If $f:X\to Y$ is injective then $\pat(f\circ x)=\pat(x)$. In particular $\pat(\sigma\circ x)=\pat(x)$ for every $\sigma\in\Sym(X)$: the kernel pattern is a $\Sym(X)$-invariant.
\end{theorem}
\begin{proof}
Injectivity gives $f(x_k)=f(x_l)\iff x_k=x_l$; apply Lemma~\ref{lem:congr}.
\end{proof}

\begin{lemma}[Idempotence]\label{lem:idem}
$\pat(\pat(x))=\pat(x)$.
\end{lemma}
\begin{proof}
Lemma~\ref{lem:faith} says $x$ and $\pat(x)$ have the same kernel; apply Lemma~\ref{lem:congr}.
\end{proof}

\begin{proposition}[Pointwise characterisation]\label{prop:fixed}
For $p:[n]\to[n]$,
\[
  \pat(p)=p \iff \bigl(\forall i,\ p_i\le i\bigr)\ \wedge\ \bigl(\forall i,\ p_{p_i}=p_i\bigr).
\]
\end{proposition}
\begin{proof}
($\Rightarrow$) Both conditions hold for any pattern: $\pat(x)_i\le i$ by definition, and $\pat(x)_{\pat(x)_i}=\pat(x)_i$ by Lemmas~\ref{lem:val} and~\ref{lem:faith}. ($\Leftarrow$) If $p$ is weakly regressive and idempotent then $p_{p_i}=p_i$ exhibits $p_i$ in $\{j:p_j=p_i\}$, so $\pat(p)_i\le p_i$; conversely any $j$ with $p_j=p_i$ satisfies $p_i=p_j\le j$, so $p_i$ is a lower bound and $p_i\le\pat(p)_i$.
\end{proof}

\begin{definition}
Write $\mathcal{P}_{n,m}$ for the set of patterns of $n$-tuples over an $m$-letter alphabet, and $\mathcal{P}_n:=\mathcal{P}_{n,n}$.
\end{definition}

\begin{proposition}[Membership test]\label{prop:mem}
$p\in\mathcal{P}_{n,m}$ if and only if $\pat(p)=p$ and $|\im(p)|\le m$.
\end{proposition}
\begin{proof}
If $p=\pat(x)$ then $p$ is idempotent (Lemma~\ref{lem:idem}), and $j\mapsto x_j$ is injective on $\im(\pat(x))$ by Lemma~\ref{lem:faith}, so $|\im(p)|\le|\im(x)|\le m$. Conversely, given such a $p$, choose an injection $e$ of $\im(p)$ into the alphabet; then $e\circ p$ has the kernel of $p$, so $\pat(e\circ p)=\pat(p)=p$ by Lemma~\ref{lem:congr}.
\end{proof}

\begin{corollary}[Stabilisation]\label{cor:stab}
If $n\le m$ then $\mathcal{P}_{n,m}=\mathcal{P}_n$.
\end{corollary}
\begin{proof}
An $n$-tuple has at most $n$ distinct entries, so the cardinality constraint of Proposition~\ref{prop:mem} is vacuous for $m\ge n$.
\end{proof}

\section{Completeness of the invariant}

\begin{theorem}[Reconstruction]\label{thm:recon}
Let $X$ be a \emph{finite} set and $x,y:[n]\to X$ with $\pat(x)=\pat(y)$. Then there exists $\sigma\in\Sym(X)$ with $\sigma\circ x=y$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:faith} the hypothesis is equivalent to
\begin{equation}\label{eq:star}
  x_i=x_j\iff y_i=y_j\qquad\text{for all }i,j.
\end{equation}
Let $S=\im(x)$, $T=\im(y)$. For $a\in S$ choose $i_a$ with $x_{i_a}=a$ and set $\varphi(a)=y_{i_a}$. This is independent of the choice and injective: if $y_{i_a}=y_{i_b}$ then $x_{i_a}=x_{i_b}$ by~\eqref{eq:star}, i.e. $a=b$; and if $a=b$ then any two choices have equal $x$-values, hence equal $y$-values. It is onto $T$: for $b=y_j\in T$, $\varphi(x_j)=y_i$ for some $i$ with $x_i=x_j$, whence $y_i=y_j=b$ by~\eqref{eq:star}.

Thus $\varphi:S\xrightarrow{\ \sim\ }T$. Since $X$ is finite and $|S|=|T|$, we have $|X\setminus S|=|X\setminus T|$; choose a bijection $\psi:X\setminus S\to X\setminus T$ and put $\sigma=\varphi\sqcup\psi\in\Sym(X)$. For each $i$, $\sigma(x_i)=\varphi(x_i)=y_i$.
\end{proof}

\begin{theorem}[Completeness]\label{thm:complete}
Let $X$ be finite. For all $x,y\in X^n$,
\[
  \bigl(\exists\,\sigma\in\Sym(X):\ \sigma\circ x=y\bigr)\iff \pat(x)=\pat(y).
\]
\end{theorem}
\begin{proof}
Theorem~\ref{thm:inv} and Theorem~\ref{thm:recon}.
\end{proof}

\begin{theorem}[Orbit count]\label{thm:orbits}
$\bigl|\,[m]^n/\Sym([m])\,\bigr|=|\mathcal{P}_{n,m}|$.
\end{theorem}
\begin{proof}
$\pat$ is constant on orbits (Theorem~\ref{thm:inv}), hence descends to the orbit space; the induced map is injective by Theorem~\ref{thm:recon} and surjective onto $\mathcal{P}_{n,m}$ by definition.
\end{proof}

\begin{proposition}[Sharpness]\label{prop:sharp}
The kernel pattern is \emph{not} complete for a proper subgroup. Take $X=\{0,1\}$, $n=1$, $G=\{\mathrm{id}\}\le\Sym(X)$. Then $\pat((0))=\pat((1))=(1)$, but no $\sigma\in G$ carries $(0)$ to $(1)$.
\end{proposition}
\begin{proof}
In a one-entry tuple the unique value first occurs at position $1$, so both patterns equal $(1)$; and $\mathrm{id}\circ(0)=(0)\ne(1)$.
\end{proof}

\section{Patterns are set partitions, and the Bell numbers}

\subsection{The bijection with equivalence relations}

\begin{definition}
For a tuple $x$, let $\ker(x)$ denote the equivalence relation $i\sim j\iff x_i=x_j$ on $[n]$.
\end{definition}

\begin{theorem}[Patterns $=$ partitions]\label{thm:partitions}
The map $p\mapsto\ker(p)$ is a bijection from $\mathcal{P}_n$ onto the equivalence relations on $[n]$, equivalently onto the set partitions of $[n]$.
\end{theorem}
\begin{proof}
\emph{Injectivity.} If $\ker(p)=\ker(q)$ with $p,q\in\mathcal{P}_n$ then $\pat(p)=\pat(q)$ by Lemma~\ref{lem:congr}, and both are $\pat$-fixed, so $p=q$.
\emph{Surjectivity.} Given $\sim$, let $q:[n]\to[n]/\!\sim$ be the quotient map and $p=\pat(q)$; then $p\in\mathcal{P}_n$ by Lemma~\ref{lem:idem} and Corollary~\ref{cor:stab}, and $\ker(p)=\ker(q)=\sim$ by Lemma~\ref{lem:faith}.
\end{proof}

Concretely, the block of $i$ is $\{j:p_j=p_i\}$ and $p_i$ is its least element: patterns encode partitions by naming each block after its minimum.

\subsection{Refining by block count: the Stirling numbers}

\begin{definition}
$\mathcal{P}_n^{(k)}=\{p\in\mathcal{P}_n:|\im(p)|=k\}$, the patterns with exactly $k$ blocks.
\end{definition}

\begin{definition}[Restriction and extension]
For $p\in\mathcal{P}_{n+1}$ let $\restr(p):[n]\to[n]$, $\restr(p)_i=p_i$ (legitimate since $p_i\le i\le n$). For $q\in\mathcal{P}_n$ and $a\in[n+1]$ let $\ext(q,a):[n+1]\to[n+1]$ agree with $q$ on $[n]$ and send $n+1$ to $a$.
\end{definition}

\begin{lemma}\label{lem:restr}
$\ext(\restr(p),p_{n+1})=p$ for $p\in\mathcal{P}_{n+1}$, and $\restr(\ext(q,a))=q$. Moreover $\ext(q,a)$ is a pattern precisely when $a=n+1$ or $a\in\im(q)$.
\end{lemma}
\begin{proof}
The identities are immediate. For the last claim apply Proposition~\ref{prop:fixed}: regressivity forces $a\le n+1$, and idempotence forces $q_a=a$ when $a\le n$, i.e. $a$ is a block representative; conversely both conditions suffice.
\end{proof}

\begin{theorem}[Stirling recursion for patterns]\label{thm:stirlingrec}
$\bigl|\mathcal{P}_{n+1}^{(k+1)}\bigr|=(k+1)\bigl|\mathcal{P}_{n}^{(k+1)}\bigr|+\bigl|\mathcal{P}_{n}^{(k)}\bigr|$.
\end{theorem}
\begin{proof}
Split according to whether $p_{n+1}=n+1$. If so, the last index is a new singleton block and, by Lemma~\ref{lem:restr}, such $p$ correspond bijectively to $q\in\mathcal{P}_n^{(k)}$. If not, the last index maps into $\im(q)$ for $q=\restr(p)$, the image is unchanged so $q\in\mathcal{P}_n^{(k+1)}$, and $p$ is determined by $q$ plus a choice among the $k+1$ representatives.
\end{proof}

\begin{theorem}\label{thm:stirling}
$\bigl|\mathcal{P}_n^{(k)}\bigr|=S(n,k)$ for all $n,k$, and hence $|\mathcal{P}_n|=\sum_{k=0}^{n}S(n,k)$.
\end{theorem}
\begin{proof}
Induction on $n$ from Theorem~\ref{thm:stirlingrec} and the boundary values $|\mathcal{P}_0^{(0)}|=1$, $|\mathcal{P}_0^{(k+1)}|=0$, $|\mathcal{P}_{n+1}^{(0)}|=0$, which are exactly those of the Stirling triangle. The sum is the fibre decomposition of $\mathcal{P}_n$ along $p\mapsto|\im(p)|$.
\end{proof}

\subsection{The total count: the Bell recursion}

\begin{definition}
For $p\in\mathcal{P}_{n+1}$ put $\lastBlk(p)=\{i\in[n]:p_i=p_{n+1}\}\subseteq[n]$.
\end{definition}

\begin{theorem}[Fibre over the last block]\label{thm:lastblk}
For each $S\subseteq[n]$, the patterns $p\in\mathcal{P}_{n+1}$ with $\lastBlk(p)=S$ are in bijection with the equivalence relations on $[n]\setminus S$; there are $B_{\,n-|S|}$ of them.
\end{theorem}
\begin{proof}[Proof sketch]
Given $p$ in the fibre, restrict $\ker(p)$ to $[n]\setminus S$. Conversely, given an equivalence relation $t$ on $[n]\setminus S$, define $b:[n+1]\to\bigl(([n]\setminus S)/t\bigr)\sqcup\{\ast\}$ collapsing $S\cup\{n+1\}$ to $\ast$ and sending $i\notin S$ to its $t$-class, and set $p=\pat(b)$. Then $p$ is a pattern (Lemma~\ref{lem:idem}) whose kernel is ``$S\cup\{n+1\}$ is one block and $t$ partitions the complement'', so $\lastBlk(p)=S$; the two constructions invert one another by Lemma~\ref{lem:congr}, each determining the kernel of the other. The count follows from Theorem~\ref{thm:partitions} on the $(n-|S|)$-element set $[n]\setminus S$.
\end{proof}

\begin{theorem}[Bell recursion]\label{thm:bellrec}
$\displaystyle |\mathcal{P}_{n+1}|=\sum_{S\subseteq[n]}|\mathcal{P}_{\,n-|S|}|=\sum_{i=0}^{n}\binom{n}{i}|\mathcal{P}_{\,n-i}|$.
\end{theorem}
\begin{proof}
Fibre along $p\mapsto\lastBlk(p)$ and apply Theorems~\ref{thm:lastblk} and~\ref{thm:partitions}; then group subsets by cardinality.
\end{proof}

\begin{theorem}[Bell count]\label{thm:bell}
$|\mathcal{P}_n|=B_n$ for every $n\ge0$. Equivalently, an $n$-element set carries $B_n$ equivalence relations, and (with Theorem~\ref{thm:orbits} and Corollary~\ref{cor:stab}) the diagonal $\Sym([m])$-action on $[m]^n$ has exactly $B_n$ orbits whenever $m\ge n$.
\end{theorem}
\begin{proof}
Strong induction: $|\mathcal{P}_0|=1=B_0$, and Theorem~\ref{thm:bellrec} is the defining binomial recursion $B_{n+1}=\sum_i\binom{n}{i}B_{n-i}$.
\end{proof}

\begin{corollary}[Bell--Stirling identity]\label{cor:bellstirling}
$\displaystyle B_n=\sum_{k=0}^{n}S(n,k)$.
\end{corollary}

\begin{remark}
This identity is not formal bookkeeping: the Bell numbers are specified by the binomial recursion and the Stirling numbers by the triangle recursion, and neither recursion mentions the other. The identity holds because both count kernel patterns---one grouped by last block, one grouped by block count.
\end{remark}

\subsection{The initial segment}

Independently of the recursions, Proposition~\ref{prop:fixed} makes $|\mathcal{P}_n|$ directly computable by exhaustive search over the $n^n$ tuples $p:[n]\to[n]$. For $n\le5$ this gives
\[
  |\mathcal{P}_0|,\dots,|\mathcal{P}_5| \;=\; 1,\ 1,\ 2,\ 5,\ 15,\ 52,
\]
the Bell numbers $B_0,\dots,B_5$ (OEIS A000110), in agreement with Theorem~\ref{thm:bell}.

\section{Geometry I: flats of the braid arrangement}

\begin{definition}
The \emph{braid arrangement} in $\R^n$ is the family of hyperplanes $H_{ij}=\{v\in\R^n:v_i=v_j\}$, $1\le i<j\le n$: the reflection arrangement of $\Sym([n])$ acting by permuting coordinates. Its \emph{flats} are the intersections of subfamilies, ordered by inclusion; this poset is the \emph{intersection lattice}.
\end{definition}

\begin{definition}
For a tuple $x:[n]\to X$ put $L(x)=\{v\in\R^n:\forall i,j,\ x_i=x_j\Rightarrow v_i=v_j\}$, the subspace of vectors constant on the blocks of $\ker(x)$.
\end{definition}

$L(x)$ is exactly $\bigcap\{H_{ij}:x_i=x_j\}$, and conversely every intersection of braid hyperplanes has this form, since the relation ``$v_i=v_j$ for all $v$ in the intersection'' is an equivalence relation. So the flats are precisely the subspaces $L(x)$.

\begin{definition}
The \emph{block indicator} $\mathbf{1}^x_i\in\R^n$ has $(\mathbf{1}^x_i)_k=1$ if $x_k=x_i$ and $0$ otherwise; clearly $\mathbf{1}^x_i\in L(x)$.
\end{definition}

\begin{theorem}[Order dictionary]\label{thm:orderdict}
$L(x)\subseteq L(y)\iff\bigl(\forall i,j,\ y_i=y_j\Rightarrow x_i=x_j\bigr)$: inclusion of flats is, order-reversingly, refinement of kernels.
\end{theorem}
\begin{proof}
($\Leftarrow$) Immediate. ($\Rightarrow$) If $y_i=y_j$ then $\mathbf{1}^x_i\in L(y)$ has equal $i$- and $j$-coordinates; the $i$-coordinate is $1$, so $x_j=x_i$.
\end{proof}

\begin{theorem}[Geometric completeness]\label{thm:geomcomplete}
$L(x)=L(y)\iff\pat(x)=\pat(y)$.
\end{theorem}
\begin{proof}
($\Rightarrow$) Theorem~\ref{thm:orderdict} in both directions gives $x_i=x_j\iff y_i=y_j$; apply Lemma~\ref{lem:congr}. ($\Leftarrow$) The pattern determines the kernel (Lemma~\ref{lem:faith}), and $L$ depends only on the kernel.
\end{proof}

\begin{theorem}[Dimension $=$ number of blocks]\label{thm:dim}
$\dim_\R L(x)=|\im(\pat(x))|$.
\end{theorem}
\begin{proof}
Restriction to the block representatives, $v\mapsto(v_r)_{r\in\im(\pat(x))}$, is a linear isomorphism $L(x)\to\R^{\im(\pat(x))}$: injective because $v_i=v_{\pat(x)_i}$ for $v\in L(x)$ (Lemma~\ref{lem:val}), and surjective because $v_i:=w_{\pat(x)_i}$ defines an element of $L(x)$ (Lemma~\ref{lem:faith}).
\end{proof}

\begin{corollary}
If $x$ is injective then $L(x)=\R^n$; if $x$ is constant and $n\ge1$ then $L(x)$ is the line of constant vectors, of dimension $1$.
\end{corollary}

\begin{theorem}[Enumeration of the intersection lattice]\label{thm:flats}
The braid arrangement in $\R^n$ has exactly $B_n$ flats, of which exactly $S(n,k)$ have dimension $k$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:geomcomplete}, $p\mapsto L(p)$ is a bijection from $\mathcal{P}_n$ onto the flats; apply Theorem~\ref{thm:bell} and, for the refinement, Theorems~\ref{thm:dim} and~\ref{thm:stirling}.
\end{proof}

For $n=5$ there are $52$ flats, of dimensions $1,2,3,4,5$ in quantities $1,15,25,10,1$.

\section{Geometry II: faces, chambers, and the Fubini numbers}

\begin{definition}[Ordered pattern]\label{def:rank}
Let $X$ be linearly ordered and $v:[n]\to X$. Set
\[
  \rank(v)_i=\#\{\,j:\pat(v)_j=j\ \wedge\ v_j<v_i\,\},
\]
the number of distinct values of $v$ strictly below $v_i$.
\end{definition}

\begin{example}
$v=(3.1,7.0,3.1,-2.0,7.0)$ has distinct values $-2.0<3.1<7.0$ and $\rank(v)=(1,2,1,0,2)$.
\end{example}

\begin{theorem}[Order faithfulness]\label{thm:rankfaith}
$\rank(v)_i<\rank(v)_j\iff v_i<v_j$, and consequently $\rank(v)_i=\rank(v)_j\iff v_i=v_j$.
\end{theorem}
\begin{proof}
If $v_i<v_j$, the representatives with value $<v_i$ form a proper subset of those with value $<v_j$---proper because $\pat(v)_i$ lies in the second and not the first---so the cardinalities are strictly ordered. If $v_i\ge v_j$ the inclusion goes the other way. Trichotomy gives the equality statement.
\end{proof}

\begin{theorem}[Invariance]\label{thm:rankinv}
If $f$ is strictly monotone then $\rank(f\circ v)=\rank(v)$; more generally $\rank(v)$ depends only on the weak order induced by $v$. Moreover $\rank(\rank(v))=\rank(v)$ and $\pat(\rank(v))=\pat(v)$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:rankfaith} the data $\{(i,j):v_i<v_j\}$ determines $\rank(v)$, and strictly monotone reparametrisation preserves that data; idempotence and compatibility with $\pat$ follow from Theorem~\ref{thm:rankfaith} and Lemma~\ref{lem:congr}.
\end{proof}

Write $\mathcal{O}_n=\{r:\rank(r)=r\}$ for the ordered patterns and $\mathcal{O}_n^{(k)}$ for those with $k$ distinct values.

\begin{definition}
The \emph{face} of $v\in\R^n$ is $F(v)=\{w\in\R^n:\forall i,j,\ (v_i<v_j\iff w_i<w_j)\}$, the relatively open cone realising the same comparisons as $v$.
\end{definition}

\begin{theorem}[Faces are convex]\label{thm:faceconvex}
Each $F(v)$ is convex, hence connected, and contains $v$.
\end{theorem}
\begin{proof}
Let $w,w'\in F(v)$, $a,b\ge0$, $a+b=1$. If $v_i<v_j$ then $w_i<w_j$ and $w'_i<w'_j$, and a convex combination of two strict inequalities is strict. If $v_i=v_j$ then $w_i=w_j$ and $w'_i=w'_j$, so the combination has equal coordinates. The case $v_j<v_i$ is symmetric.
\end{proof}

\begin{theorem}[Ordered patterns classify faces]\label{thm:faceclass}
$F(v)=F(w)\iff\rank(v)=\rank(w)$.
\end{theorem}
\begin{proof}
($\Rightarrow$) $w\in F(w)=F(v)$ says $v,w$ realise the same strict comparisons; apply Theorem~\ref{thm:rankinv}. ($\Leftarrow$) Theorem~\ref{thm:rankfaith} gives $v_i<v_j\iff w_i<w_j$, so both faces are defined by the same conditions.
\end{proof}

\begin{definition}
For $\sigma\in\Sym([n])$ let $C_\sigma=\{v\in\R^n:v_{\sigma(1)}<\cdots<v_{\sigma(n)}\}$.
\end{definition}

\begin{theorem}[Chamber structure]\label{thm:chambers}
Each $C_\sigma$ is nonempty and convex; distinct permutations give disjoint chambers; $\sigma\mapsto C_\sigma$ is injective; and $\bigcup_\sigma C_\sigma$ is exactly the set of injective vectors, i.e.\ the complement of the arrangement. Hence the braid arrangement in $\R^n$ has exactly $n!$ chambers.
\end{theorem}
\begin{proof}
Take $v_{\sigma(i)}=i$ for nonemptiness; the defining conditions are strict linear inequalities, whence convexity. Any $v\in C_\sigma$ is injective and $\sigma$ is the unique permutation sorting $v$ increasingly, giving disjointness and injectivity; conversely an injective $v$ lies in $C_\sigma$ for its sorting permutation.
\end{proof}

\begin{theorem}[Chambers are faces]\label{thm:chamberface}
If $v\in C_\sigma$ then $F(v)=C_\sigma$.
\end{theorem}
\begin{proof}
Both sets consist exactly of the $w$ with $w_{\sigma(1)}<\cdots<w_{\sigma(n)}$.
\end{proof}

\begin{theorem}[Fibre theorem]\label{thm:fibre}
Let $p\in\mathcal{P}_n$ have exactly $k$ blocks. Then $\#\{r\in\mathcal{O}_n:\pat(r)=p\}=k!$.
\end{theorem}
\begin{proof}[Proof sketch]
An ordered pattern over $p$ is the same data as $p$ together with a linear order of its $k$ blocks: given such an order, $r_i:=\#\{\text{blocks strictly preceding the block of }i\}$ is an ordered pattern with $\pat(r)=p$ (Theorem~\ref{thm:rankinv}), and by Theorem~\ref{thm:rankfaith} every ordered pattern over $p$ is constant on blocks of $p$ and totally orders them, so arises exactly once. A $k$-element set has $k!$ linear orders. (The rigidity input: an ordered pattern with $k$ distinct values, viewed as a surjection onto $\{0,\dots,k-1\}$, equals its own rank function.)
\end{proof}

\begin{theorem}[Fubini formula]\label{thm:fubini}
$\bigl|\mathcal{O}_n^{(k)}\bigr|=S(n,k)\,k!$ and $\displaystyle|\mathcal{O}_n|=\sum_{k=0}^{n}S(n,k)\,k!$.
\end{theorem}
\begin{proof}
Fibre $\pat:\mathcal{O}_n^{(k)}\to\mathcal{P}_n^{(k)}$: each fibre has $k!$ elements (Theorem~\ref{thm:fibre}) and the base has $S(n,k)$ elements (Theorem~\ref{thm:stirling}); sum over $k$.
\end{proof}

The numbers $a_n=\sum_k S(n,k)k!$ are the ordered Bell (Fubini) numbers, OEIS A000670: $1,1,3,13,75,541,4683,\dots$ They count the weak orderings of an $n$-set, equivalently the faces of the braid arrangement in $\R^n$.

\begin{theorem}[Comparisons]\label{thm:compare}
For all $n$: $n!\le a_n$ and $B_n\le a_n$.
\end{theorem}
\begin{proof}
$n!=S(n,n)\,n!$ is a single term of the Fubini sum and all terms are non-negative; and $S(n,k)\le S(n,k)k!$ term by term, with $B_n=\sum_k S(n,k)$ by Corollary~\ref{cor:bellstirling}.
\end{proof}

Geometrically: every chamber is a face (Theorem~\ref{thm:chamberface}), and every flat carries at least one face.

