function STIRLING_TRIANGLE(N):
    S[0][0] <- 1
    for n <- 1 to N:
        for k <- 1 to n:
            S[n][k] <- S[n-1][k-1] + k * S[n-1][k]      # 0 when out of range
    return S

function BELL(N):
    B[0] <- 1
    for n <- 0 to N-1:
        B[n+1] <- sum over i = 0..n of C(n,i) * B[n-i]
    return B

function FUBINI(N):
    S <- STIRLING_TRIANGLE(N)
    for n <- 0 to N: a[n] <- sum over k = 0..n of S[n][k] * k!
    return a

assert for all n <= N:  sum_k S[n][k] = B[n]  and  n! <= a[n]  and  B[n] <= a[n]

function FLAT_DATA(v[0..n-1]):
    p <- KERNEL_PATTERN(v)                       # names the flat
    B <- blocks of p, sorted by least element
    k <- |B|                                     # dimension of the flat
    basis <- [ indicator vector of b : b in B ]
    vals  <- sorted(distinct entries of v)
    r[i]  <- index of v[i] in vals               # names the face
    chamber <- (k = n) ? sorting permutation of v : NONE
    return (p, B, k, basis, r, k!, chamber)

function SAME_FLAT(v,w): return KERNEL_PATTERN(v) = KERNEL_PATTERN(w)
function SAME_FACE(v,w): return ORDERED_PATTERN(v) = ORDERED_PATTERN(w)

