"""Algorithm 4 - Locating a real vector in the braid arrangement: flat, face, chamber."""

from __future__ import annotations

from math import factorial
from typing import Dict, Hashable, List, Optional, Sequence, Tuple


def kernel_pattern(v: Sequence[Hashable]) -> Tuple[int, ...]:
    """pat(v)_i = index of the first occurrence of the value v_i."""
    first: Dict[Hashable, int] = {}
    out: List[int] = []
    for i, value in enumerate(v):
        first.setdefault(value, i)
        out.append(first[value])
    return tuple(out)


def ordered_pattern(v: Sequence[float]) -> Tuple[int, ...]:
    """rank(v)_i = number of distinct values of v strictly below v_i.  O(n log n)."""
    order = {value: k for k, value in enumerate(sorted(set(v)))}
    return tuple(order[value] for value in v)


def flat_data(v: Sequence[float]) -> Dict[str, object]:
    """Full location of v in the braid arrangement.

    Returns the kernel pattern (naming the flat), the blocks, the dimension of
    the flat (= number of blocks), a basis of the flat (block indicators), the
    ordered pattern (naming the face), the number k! of faces on that flat, and
    the chamber permutation when v is injective (else None).
    """
    n = len(v)
    p = kernel_pattern(v)
    groups: Dict[int, List[int]] = {}
    for i, a in enumerate(p):
        groups.setdefault(a, []).append(i)
    blocks = sorted(groups.values(), key=min)
    k = len(blocks)
    basis = [[1.0 if i in b else 0.0 for i in range(n)] for b in blocks]
    chamber: Optional[Tuple[int, ...]] = (
        tuple(sorted(range(n), key=lambda i: v[i])) if k == n else None
    )
    return {
        "kernel_pattern": p,
        "blocks": blocks,
        "dimension": k,
        "basis": basis,
        "ordered_pattern": ordered_pattern(v),
        "faces_on_flat": factorial(k),
        "chamber": chamber,
    }


def same_flat(v: Sequence[float], w: Sequence[float]) -> bool:
    """v and w cut out the same flat iff their kernel patterns agree."""
    return kernel_pattern(v) == kernel_pattern(w)


def same_face(v: Sequence[float], w: Sequence[float]) -> bool:
    """v and w lie in the same face iff their ordered patterns agree."""
    return ordered_pattern(v) == ordered_pattern(w)


if __name__ == "__main__":
    v = [3.1, 7.0, 3.1, -2.0, 7.0]
    for key, value in flat_data(v).items():
        print(f"{key:16s}: {value}")
    stretched = [2 * t + 5 for t in v]
    print("monotone image same face :", same_face(v, stretched))
    reordered = [3.1, 7.0, 3.1, 5.0, 7.0]
    print("reordered same flat      :", same_flat(v, reordered))
    print("reordered same face      :", same_face(v, reordered))

