"""
The intersection lattice of the braid arrangement, drawn as the partition
lattice of {0,...,n-1} ordered by refinement.

Nodes are kernel patterns, drawn at height equal to the number of blocks, which
by the dimension theorem is the dimension of the corresponding flat.  Edges join
a partition to those obtained by merging two of its blocks (covering relations).
For n = 4 the picture has 15 nodes in rows of sizes 1, 7, 6, 1 -- the Stirling
numbers S(4,1), S(4,2), S(4,3), S(4,4) -- summing to the Bell number B_4 = 15.

Run: python3 viz_lattice.py     (writes braid_lattice.png)
"""

from __future__ import annotations

from typing import Dict, List, Tuple

import matplotlib.pyplot as plt


def all_patterns(n: int) -> List[Tuple[int, ...]]:
    """All kernel patterns of length n (restricted growth search)."""
    out: List[Tuple[int, ...]] = []

    def extend(prefix: List[int]) -> None:
        if len(prefix) == n:
            out.append(tuple(prefix))
            return
        i = len(prefix)
        for a in sorted(set(prefix) | {i}):
            prefix.append(a)
            extend(prefix)
            prefix.pop()

    extend([])
    return out


def blocks_of(p: Tuple[int, ...]) -> List[List[int]]:
    groups: Dict[int, List[int]] = {}
    for i, v in enumerate(p):
        groups.setdefault(v, []).append(i)
    return sorted(groups.values(), key=min)


def canonical(assignment: List[int]) -> Tuple[int, ...]:
    """Kernel pattern of an arbitrary block-labelling."""
    first: Dict[int, int] = {}
    out: List[int] = []
    for i, v in enumerate(assignment):
        first.setdefault(v, i)
        out.append(first[v])
    return tuple(out)


def merges(p: Tuple[int, ...]) -> List[Tuple[int, ...]]:
    """Partitions covering p: merge two blocks."""
    bl = blocks_of(p)
    out = []
    for a in range(len(bl)):
        for b in range(a + 1, len(bl)):
            lab = list(p)
            for i in bl[b]:
                lab[i] = p[bl[a][0]]
            out.append(canonical(lab))
    return out


def label(p: Tuple[int, ...]) -> str:
    return "|".join("".join(str(i) for i in b) for b in blocks_of(p))


def main(n: int = 4) -> None:
    pats = all_patterns(n)
    rows: Dict[int, List[Tuple[int, ...]]] = {}
    for p in pats:
        rows.setdefault(len(blocks_of(p)), []).append(p)

    pos: Dict[Tuple[int, ...], Tuple[float, float]] = {}
    for k, row in rows.items():
        row.sort(key=label)
        for j, p in enumerate(row):
            pos[p] = ((j - (len(row) - 1) / 2) * 1.6, float(k))

    fig, ax = plt.subplots(figsize=(12, 6.5))
    for p in pats:
        for q in merges(p):
            x1, y1 = pos[p]
            x2, y2 = pos[q]
            ax.plot([x1, x2], [y1, y2], color="#bbb", lw=0.9, zorder=1)
    colours = {1: "#c0392b", 2: "#d8863b", 3: "#3b7dd8", 4: "#2e8b57", 5: "#7d3bd8"}
    for p, (x, y) in pos.items():
        k = len(blocks_of(p))
        ax.scatter([x], [y], s=560, color=colours.get(k, "#555"), zorder=2, alpha=0.9)
        ax.text(x, y, label(p), ha="center", va="center", fontsize=8, color="white", zorder=3)

    for k, row in sorted(rows.items()):
        ax.text(
            min(x for x, y in pos.values()) - 1.9,
            k,
            f"dim {k}\nS({n},{k}) = {len(row)}",
            fontsize=9,
            va="center",
            color=colours.get(k, "#555"),
        )

    ax.set_title(
        f"Intersection lattice of the braid arrangement in $\\mathbb{{R}}^{n}$: "
        f"{len(pats)} flats $= B_{n}$\n"
        "height = number of blocks = dimension of the flat; "
        "edges are covering merges of two blocks"
    )
    ax.set_xticks([])
    ax.set_yticks(sorted(rows))
    ax.set_ylabel("dimension")
    ax.set_frame_on(False)
    fig.tight_layout()
    fig.savefig("braid_lattice.png", dpi=160)
    print("wrote braid_lattice.png")
    for k, row in sorted(rows.items()):
        print(f"  dimension {k}: {len(row)} flats  ->  " + ", ".join(label(p) for p in row))


if __name__ == "__main__":
    main()
